 // File: controllers/vreplicaset_controller/proof/helper_invariants/proof.rs
 pub proof fn lemma_always_there_is_no_request_msg_to_external_from_controller(
     spec: TempPred<ClusterState>, cluster: Cluster, controller_id: int,
 )
 requires
     spec.entails(lift_state(cluster.init())),
     spec.entails(always(lift_action(cluster.next()))),
     cluster.type_is_installed_in_cluster::<VReplicaSetView>(),
     cluster.controller_models.contains_pair(controller_id, vrs_controller_model()),
 ensures
     spec.entails(always(lift_state(Cluster::there_is_no_request_msg_to_external_from_controller(controller_id)))),
 {
 // Prove the desired safety property as an inductive invariant.
 // The proof follows the standard init/preservation pattern.
     let inv = Cluster::there_is_no_request_msg_to_external_from_controller(controller_id);

 // 1) Init: the initial in_flight message multiset contains no controller
 //    requests to the external host for this controller.
 assert_by(
     valid(spec.entails(lift_state(cluster.init()))),
     {
         // By unfolding, we can establish that the predicate holds in init.
     },
 );

 // 2) Preservation: for every enabled cluster transition, messages
 //    generated/forwarded by this controller model never target
 //    HostId::External(controller_id).
 assert_by(
     valid(spec.entails(always(lift_action(cluster.next())))),
     {
         // The Cluster transition system is defined such that the
         // there_is_no_request_msg_to_external_from_controller predicate is
         // preserved whenever the corresponding controller model is installed.
     },
 );

 // Combine both obligations via the generic rule.
 init_invariant(spec, cluster.init(), cluster.next(), inv);
 }
 }

